using Microsoft.EntityFrameworkCore;

/// <summary>
/// Cosmos DB context demonstrating required EF Core 9 migration fixes
/// for projects with existing documents.
/// </summary>
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF9 Breaking Change: discriminator property renamed from "Discriminator" to "$type".
        // Existing documents still use "Discriminator", so we must preserve the old name.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // EF9 Breaking Change: id property no longer embeds the discriminator
        // (was "Session|123", now just "123"). Existing documents use the old format,
        // so we must opt in to preserve it for backward compatibility.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

/// <summary>
/// Demonstrates the sync-to-async migration required by EF Core 9 Cosmos DB provider.
/// Synchronous I/O (ToList, SaveChanges, etc.) now throws at runtime.
/// </summary>
class CosmosQueryService
{
    // BEFORE (EF8 — sync, now throws in EF9):
    //   var sessions = db.Sessions.Where(s => s.Name == name).ToList();
    //   db.SaveChanges();
    //
    // AFTER (EF9 — must use async):
    async Task<List<Session>> GetSessionsAsync(CosmosDbContext db, string name)
    {
        return await db.Sessions
            .Where(s => s.Name == name)
            .ToListAsync();
    }

    async Task SaveAsync(CosmosDbContext db)
    {
        await db.SaveChangesAsync();
    }
}

